/** Paired EN/HI catalog for dashamsaPractical localization. */
export function pair(key, en, hi) {
  return { key, en, hi }
}

export function buildAllEntries() {
  return [
    ...charity(),
    ...karma(),
    ...pending(),
    ...combos(),
    ...bondage(),
    ...karmaYoga(),
    ...circuit(),
    ...survival(),
    ...sectorsUi(),
  ]
}

