function yesHi(id, en) { return enHiCombo[id]?.yes ?? hindiWrap(en) }
function noHi(id, en) { return enHiCombo[id]?.no ?? hindiWrap(en) }
function singleHi(id, en) { return enHiCombo[id]?.single ?? hindiWrap(en) }

